    "/call-upload": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Upload a call recording
         * @description Accepts multipart/form-data uploads compatible with trunk-recorder's
         *     rdio-scanner and OpenMHz upload plugins. Auto-detects format from form
         *     field names.
         *
         *     This provides a third ingest path alongside MQTT and file-watch. Point
         *     trunk-recorder's upload plugin at `POST /api/v1/call-upload` and it
         *     works out of the box.
         *
         *     **Authentication:** needs an API key with the `upload` scope
         *     (create one with `tr-engine keys create --name "tr butco uploads"
         *     --scopes upload`). Anonymous access never allows uploads, and
         *     `listen`/`edit`/`admin` keys without `upload` are refused with 403
         *     `insufficient_scope`. The key is read from, in order:
         *
         *     1. the `Authorization: Bearer <key>` header;
         *     2. the multipart form field `key` (rdio-scanner plugin);
         *     3. the multipart form field `api_key` (OpenMHz plugin).
         *
         *     Form fields are read from the multipart body only (never from the
         *     URL), after the 50 MB upload size limit (a larger body is 413,
         *     whether the key is in the header or the form). A field that is
         *     present but holds an unknown, revoked or expired key is 401
         *     `invalid_key`; the other field is not tried. Without a Bearer
         *     header, a body that isn't `multipart/form-data` has no key fields
         *     and is 401 `key_required`, and so is a form field holding the
         *     pre-upgrade public `AUTH_TOKEN` (it counts as no key). Rejected
         *     uploads are logged with the client IP, the form's system name and
         *     the reason.
         *
         *     **Rate limits:** an upload that carries its key in a form field
         *     has no header credential, so it is limited per client IP
         *     (`RATE_LIMIT_RPS`/`RATE_LIMIT_BURST`) like a request without a
         *     key. It costs two per-IP tokens when the key isn't in the
         *     30-second key cache, and always for a legacy (imported) key such
         *     as an imported `WRITE_TOKEN`, so those uploads get half the
         *     per-IP rate. A host that uploads many calls per second (for
         *     example while clearing a backlog) should send the key as
         *     `Authorization: Bearer` (a legacy key stays limited per IP there
         *     too, at one token per request; replace it with a new `upload`
         *     key), or the operator should raise the per-IP limits.
         *
         *     **Format detection:** The endpoint inspects form field names to
         *     determine the upload format:
         *     - Fields `audio`, `audioName`, or `systemLabel` → **rdio-scanner** format
         *     - Fields `call`, `talkgroup_num`, or `start_time` → **OpenMHz** format
         *
         *     **rdio-scanner format fields:**
         *
         *     | Field | Type | Required | Description |
         *     |-------|------|----------|-------------|
         *     | `audio` | file | Yes | Audio file (m4a, wav, mp3) |
         *     | `talkgroup` | integer | Yes | Talkgroup ID |
         *     | `dateTime` | integer | Yes | Unix epoch timestamp |
         *     | `systemLabel` | string | Yes | System short name (used for identity resolution) |
         *     | `frequency` | integer | No | Frequency in Hz |
         *     | `sources` | JSON string | No | Array of `[{pos, src, tag}]` source items |
         *     | `frequencies` | JSON string | No | Array of `[{freq, time, pos, len, errors, spikes}]` |
         *     | `talkgroupLabel` | string | No | Talkgroup alpha tag |
         *     | `talkgroupName` | string | No | Talkgroup description |
         *     | `talkgroupTag` | string | No | Talkgroup service tag |
         *     | `talkgroupGroup` | string | No | Talkgroup group/category |
         *     | `audioType` | string | No | MIME type (e.g., `audio/mp4`) |
         *     | `audioName` | string | No | Original filename |
         *     | `emergency` | boolean | No | Emergency flag |
         *     | `encrypted` | boolean | No | Encrypted flag |
         *     | `key` | string | No | API key with the `upload` scope (alternative to the Bearer header) |
         *
         *     **OpenMHz format fields:**
         *
         *     | Field | Type | Required | Description |
         *     |-------|------|----------|-------------|
         *     | `call` | file | Yes | Audio file |
         *     | `talkgroup_num` | integer | Yes | Talkgroup ID |
         *     | `start_time` | integer | Yes | Unix epoch start time |
         *     | `freq` | integer | No | Frequency in Hz |
         *     | `stop_time` | integer | No | Unix epoch stop time |
         *     | `call_length` | number | No | Call duration in seconds |
         *     | `source_list` | JSON string | No | Array of source items |
         *     | `emergency` | integer | No | Emergency flag (0/1) |
         *     | `error_count` | integer | No | Decode error count |
         *     | `api_key` | string | No | API key with the `upload` scope (alternative to the Bearer header) |
         */
        post: operations["uploadCall"];
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
